import os
import ast
import operator
from flask import Flask, request, jsonify, abort
import hashlib
import hmac
import time
import re

app = Flask(__name__)

SECRET_KEY = os.environ.get('SECRET_KEY', os.urandom(32))
BASE_DIR = '/var/www/uploads'
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.doc'}

def constant_time_compare(a, b):
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def generate_token(username):
    ts = str(int(time.time()) // 300)
    return hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(),
                    f"{username}:{ts}".encode(), hashlib.sha256).hexdigest()

def verify_token(username, token):
    expected = generate_token(username)
    return constant_time_compare(expected, token)

# Safe expression evaluator using AST - ONLY allows arithmetic on literals
SAFE_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
}

def safe_eval_expr(expr_str):
    """Evaluate simple arithmetic expressions safely.
    Only supports integer/float literals and +, -, *, / operators.
    This is NOT using eval() - it parses the AST and only allows
    numeric literals and basic binary operations."""
    if not isinstance(expr_str, str):
        raise ValueError("Expression must be a string")
    if len(expr_str) > 100:
        raise ValueError("Expression too long")
    # Whitelist characters
    if not re.match(r'^[0-9+\-*/().\s]+$', expr_str):
        raise ValueError("Invalid characters in expression")
    try:
        tree = ast.parse(expr_str, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid expression syntax")
    return _eval_node(tree.body)

def _eval_node(node):
    """Recursively evaluate AST nodes - only Num/BinOp/UnaryOp allowed."""
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        if abs(node.value) > 1e15:
            raise ValueError("Number too large")
        return node.value
    elif isinstance(node, ast.BinOp):
        if type(node.op) not in SAFE_OPS:
            raise ValueError(f"Unsupported operator: {type(node.op).__name__}")
        left = _eval_node(node.left)
        right = _eval_node(node.right)
        if isinstance(node.op, ast.Div) and right == 0:
            raise ValueError("Division by zero")
        result = SAFE_OPS[type(node.op)](left, right)
        if abs(result) > 1e15:
            raise ValueError("Result too large")
        return result
    elif isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
        return -_eval_node(node.operand)
    else:
        raise ValueError(f"Unsupported expression node: {type(node).__name__}")

def sanitize_filename(filename):
    """Sanitize filename to prevent path traversal."""
    if not isinstance(filename, str):
        return None
    # Strip null bytes
    filename = filename.replace('\x00', '')
    # Reject any path separators
    if '/' in filename or '\\' in filename:
        return None
    # Reject path traversal attempts
    if '..' in filename:
        return None
    # Validate extension
    ext = os.path.splitext(filename)[1].lower()
    if ext not in ALLOWED_EXTENSIONS:
        return None
    # Reject hidden files
    if filename.startswith('.'):
        return None
    # Check length
    if len(filename) > 255 or len(filename) == 0:
        return None
    return filename

def build_safe_path(username, filename):
    """Build a safe file path within the user's directory."""
    clean_name = sanitize_filename(filename)
    if clean_name is None:
        return None
    user_dir = os.path.join(BASE_DIR, username)
    full_path = os.path.join(user_dir, clean_name)
    # Final check: ensure the resolved path is under BASE_DIR
    resolved = os.path.realpath(full_path)
    base_resolved = os.path.realpath(BASE_DIR)
    if not resolved.startswith(base_resolved + os.sep) and resolved != base_resolved:
        return None
    return resolved  # Return resolved path to prevent TOCTOU

@app.route('/api/files/<username>', methods=['GET'])
def list_files(username):
    token = request.headers.get('X-Auth-Token', '')
    if not verify_token(username, token):
        abort(403)
    user_dir = os.path.realpath(os.path.join(BASE_DIR, username))
    if not user_dir.startswith(os.path.realpath(BASE_DIR) + os.sep):
        abort(403)
    if not os.path.isdir(user_dir):
        return jsonify([])
    files = os.listdir(user_dir)
    return jsonify(files)

@app.route('/api/files/<username>/read', methods=['POST'])
def read_file(username):
    token = request.headers.get('X-Auth-Token', '')
    if not verify_token(username, token):
        abort(403)
    data = request.get_json()
    if not data or 'filename' not in data:
        abort(400)
    filename = data['filename']
    safe_path = build_safe_path(username, filename)
    if safe_path is None:
        abort(403)
    if not os.path.isfile(safe_path):
        abort(404)
    with open(safe_path, 'r') as f:
        content = f.read(4096)  # Limit read size
    return jsonify({'content': content, 'filename': os.path.basename(safe_path)})

@app.route('/api/files/<username>/write', methods=['POST'])
def write_file(username):
    token = request.headers.get('X-Auth-Token', '')
    if not verify_token(username, token):
        abort(403)
    data = request.get_json()
    if not data or 'filename' not in data or 'content' not in data:
        abort(400)
    filename = data['filename']
    content = data['content']
    if not isinstance(content, str) or len(content) > 1048576:
        abort(400)
    safe_path = build_safe_path(username, filename)
    if safe_path is None:
        abort(403)
    user_dir = os.path.dirname(safe_path)
    os.makedirs(user_dir, exist_ok=True)
    with open(safe_path, 'w') as f:
        f.write(content)
    return jsonify({'status': 'ok'})

@app.route('/api/calc', methods=['POST'])
def calculate():
    """Calculator endpoint - uses safe AST-based evaluation.
    WARNING: This does NOT use eval(). It only supports numeric
    literals and basic arithmetic via AST parsing."""
    data = request.get_json()
    if not data or 'expression' not in data:
        abort(400)
    expr = data['expression']
    try:
        result = safe_eval_expr(expr)
    except (ValueError, TypeError) as e:
        return jsonify({'error': str(e)}), 400
    return jsonify({'result': result})

@app.route('/api/files/<username>/search', methods=['POST'])
def search_files(username):
    """Search for files by pattern - uses safe regex matching."""
    token = request.headers.get('X-Auth-Token', '')
    if not verify_token(username, token):
        abort(403)
    data = request.get_json()
    if not data or 'pattern' not in data:
        abort(400)
    pattern = data['pattern']
    if not isinstance(pattern, str) or len(pattern) > 50:
        abort(400)
    # Only allow simple glob-like patterns
    if not re.match(r'^[a-zA-Z0-9_.*?\-]+$', pattern):
        abort(400)
    # Convert glob to regex safely
    regex_pattern = pattern.replace('.', '\\.').replace('*', '.*').replace('?', '.')
    try:
        compiled = re.compile(regex_pattern, re.IGNORECASE)
    except re.error:
        abort(400)
    user_dir = os.path.realpath(os.path.join(BASE_DIR, username))
    if not user_dir.startswith(os.path.realpath(BASE_DIR) + os.sep):
        abort(403)
    if not os.path.isdir(user_dir):
        return jsonify([])
    matches = [f for f in os.listdir(user_dir) if compiled.match(f)]
    return jsonify(matches)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
